Algoritmo PrimerDesaprobado
  Dimension notas[6] Como Entero;
  Para i <- 0 Hasta 5 Hacer
    Leer notas[i];
  FinPara
  Definir posicion Como Entero <- -1;
  Para i <- 0 Hasta 5 Hacer
    Si notas[i] < 6 Entonces
      posicion <- i;
      Salir;
    FinSi
  FinPara
  Escribir posicion;
FinAlgoritmo
